-- FaceLibrary (SLA-868): tagged face photos for the composite render kind.
-- Landmarks/measures/verdicts are JSON text; the planner filters in code over
-- one workspace's rows (tens to low hundreds), so only the workspace key is indexed.
--
-- Mirrors the model in prisma/schema.prisma (and prisma/schema.sqlite.prisma,
-- generated by src/scripts/sync-sqlite-schema.ts).
--
-- Apply with: wrangler d1 migrations apply slashloop --remote
CREATE TABLE IF NOT EXISTS "FaceLibrary" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "workspaceId" TEXT NOT NULL,
  "imageKey" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "sourceRef" TEXT NOT NULL,
  "personName" TEXT,
  "sex" TEXT NOT NULL DEFAULT 'unknown',
  "view" TEXT NOT NULL,
  "landmarksJson" TEXT NOT NULL DEFAULT '{}',
  "measuresJson" TEXT NOT NULL DEFAULT '{}',
  "verdictsJson" TEXT NOT NULL DEFAULT '{}',
  "licence" TEXT,
  "attribution" TEXT,
  "sourceVerdictJson" TEXT,
  "taggedAt" DATETIME,
  "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "FaceLibrary_workspaceId_source_sourceRef_key"
  ON "FaceLibrary"("workspaceId", "source", "sourceRef");
CREATE INDEX IF NOT EXISTS "FaceLibrary_workspaceId_source_idx"
  ON "FaceLibrary"("workspaceId", "source");
